func normalizationPeriods(c ProfileConfig, profile, account string, w Window, f ProfileFilter) []Binding {
	periods := []Binding{}
	if profile == "" || profile == "all" {
		periods = append(periods, Binding{Start: w.Start, End: w.AttributionEnd})
	} else {
		for _, p := range c.Profiles {
			if p.ID != profile {
				continue
			}
			for _, m := range profileMemberships(c, p) {
				if m.Account == account {
					periods = append(periods, Binding{Start: m.Start, End: m.End})
				}
			}
		}
	}
	clipped := []Binding{}
	for _, p := range periods {
		p.Start = max(p.Start, w.Start, f.From)
		if p.End == 0 {
			p.End = w.AttributionEnd
		}
		p.End = min(p.End, w.AttributionEnd)
		if f.To > 0 {
			p.End = min(p.End, f.To)
		}
		if p.End > p.Start {
			clipped = append(clipped, p)
		}
	}
	sort.Slice(clipped, func(i, j int) bool { return clipped[i].Start < clipped[j].Start })
	merged := []Binding{}
	for _, p := range clipped {
		if len(merged) > 0 && p.Start <= merged[len(merged)-1].End {
			merged[len(merged)-1].End = max(merged[len(merged)-1].End, p.End)
		} else {
			merged = append(merged, p)
		}
	}
	return merged
}

func normalizeProfileWindow(w Window, obs []Observation, events []Event, book ComparisonPriceBook, f ProfileFilter, periods []Binding) ProfileNormalization {
	r := ProfileNormalization{RuleID: book.ID, Status: "unavailable", Reference: book.References[w.Provider], WindowIDs: []string{}, Notes: []string{}}
	d := windowValuation(w, book)
	if book.Policy == profileValuePolicy {
		r.Valuation = &d
	}
	stop := func(reason string) ProfileNormalization { r.Reason = reason; return r }
	if r.Reference.InputPerMillion <= 0 {
		return stop("No reference model is configured for this provider.")
	}
	if strings.HasPrefix(w.Scope, "unknown") {
		return stop("This quota pool has no verified model scope.")
	}
	if f.APIKey != "" || f.Model != "" {
		return stop("Select all API keys and models to compare against this account-wide quota meter.")
	}
	if len(periods) == 0 {
		return stop("No assigned credential interval is available inside these filters.")
	}
	points := quotaPoints(w, obs, events)

	owned := map[string]bool{}
	for _, id := range w.ObservationIDs {
		owned[id] = true
	}
	conflicts := []int64{}
	for _, o := range obs {
		if !owned[o.ID] && o.Account == w.Account && o.Kind == w.Kind && o.Scope == w.Scope && o.Start > 0 && o.Reset > o.Start {
			conflicts = append(conflicts, o.Observed)
		}
	}
	sort.Slice(conflicts, func(i, j int) bool { return conflicts[i] < conflicts[j] })
	segment := []quotaPoint{}
	activePeriod, high, plan := -1, -1.0, ""
	restarted, saturated, approximate := false, false, false
	meterNoise := false
	for _, p := range points {
		period := -1
		for i, m := range periods {
			if p.Observed >= m.Start && p.Observed < m.End {
				period = i
				break
			}
		}
		if period < 0 {
			continue
		}
		if p.TimeSource == "unknown" && (p.Source == "api_query" || p.Source == "poll") {
			p.TimeLow, p.TimeHigh, p.TimeSource = p.Observed, p.Observed, "poll_receipt"
		}
		if p.High-p.Low > 1.000001 {

			if p.High-p.Low > 2.000001 {
				segment = nil
				restarted = true
				activePeriod = -1
			}
			continue
		}
		if !timedPoint(p) {
			segment = nil
			restarted = true
			activePeriod = -1
			continue
		}
		conflict := sort.Search(len(conflicts), func(i int) bool { return conflicts[i] >= p.Observed })
		if conflict < len(conflicts) && conflicts[conflict] == p.Observed {
			segment = nil
			restarted = true
			continue
		}
		resetChanged := len(segment) > 0 && conflict > 0 && conflicts[conflict-1] > segment[len(segment)-1].Observed
		threshold := 1.000001
		if high > *p.Used && high-*p.Used <= threshold {
			meterNoise = true
		}
		if activePeriod != period || resetChanged || high-*p.Used > threshold || plan != "" && p.PlanType != "" && plan != p.PlanType {
			restarted = restarted || len(segment) > 0
			segment = nil
			high = -1
			plan = ""
			saturated = false
			approximate = false
			activePeriod = period
		}
		if p.PlanType != "" {
			plan = p.PlanType
		}
		high = math.Max(high, *p.Used)
		if *p.Used >= 100 {
			saturated = true
			continue
		}
		if saturated {
			continue
		}
		if p.TimeSource == "poll_receipt" {
			approximate = true
		}
		segment = append(segment, p)
	}
	if len(segment) < 2 {
		return stop("Two usable quota readings in the same credential period are needed.")
	}
	first, last := segment[0], segment[len(segment)-1]
	r.From, r.Through = first.Observed, last.Observed
	r.StartPercent, r.EndPercent = first.Used, last.Used
	r.Delta = *last.Used - *first.Used
	r.StartObservation, r.EndObservation = first.ID, last.ID
	r.PollTiming = approximate
	if r.Delta <= 0 || r.Through <= r.From {
		return stop("The selected readings show no measurable quota increase.")
	}
	membership := periods[activePeriod]
	for _, e := range events {
		if !inWindow(e, w) || e.Started < membership.Start || e.Started >= membership.End || e.Completed < first.TimeLow || e.Started >= last.TimeHigh {
			continue
		}
		if e.Completed < e.Started || e.HeaderTime > 0 && (e.HeaderTime < e.Started-5000 || e.HeaderTime > e.Completed+5000) {
			return stop("A request has inconsistent provider/request timing in this sample.")
		}
		value := e.Value
		if value == nil || book.Policy == profileValuePolicy {
			v := valueWindowEvent(e, book, d)
			value = &v
		}
		r.Possible.add(*value)
		if e.Started >= first.TimeHigh && e.Completed <= last.TimeLow {
			r.Contained.add(*value)
			r.ContainedRequests++
		} else {
			r.BoundaryRequests++
		}
	}
	if r.ContainedRequests+r.BoundaryRequests == 0 {
		return stop("No recorded requests overlap the measured quota interval.")
	}
	if r.Possible.Invalid > 0 {
		return stop("Inconsistent token categories prevent a comparable valuation.")
	}
	if r.Possible.Missing > 0 {
		return stop("Some nonzero token categories lack a price in this comparison's price book.")
	}
	r.Status = "available"
	if r.Possible.Tokens.WriteAssumed5m > 0 {
		r.Notes = append(r.Notes, "Assumed 5m: only unclassified historical writes in this whole completed window; reported 5m/1h counts take precedence. Allocation and quota-meter bounds remain separate.")
	}
	r.Samples = 1
	r.WindowIDs = []string{w.ID}
	setNormalizedRates(&r)
	if w.Provider == "claude" || w.Provider == "codex" || meterNoise {
		if r.Delta > 1 {
			r.RoundingUSDPerPercent = &ValueRange{float64(r.Contained.Low) / 1e9 / (r.Delta + 1), float64(r.Possible.High) / 1e9 / (r.Delta - 1)}
		}
		r.Notes = append(r.Notes, "Meter sensitivity uses the observed change ±1 percentage point; it is separate from the price/boundary range and is not a confidence interval.")
	}
	if meterNoise {
		r.Notes = append(r.Notes, "Reversals of at most one percentage point are treated as meter noise, not a reset. Larger reversals split samples. Rates remain conditional on the reported endpoint change.")
	}
	if restarted {
		r.Notes = append(r.Notes, "The sample starts after the latest meter discontinuity or credential-period boundary.")
	}
	if saturated {
		r.Notes = append(r.Notes, "Only readings before meter saturation are used.")
	}
	if w.BoundaryRevision {
		r.Notes = append(r.Notes, "Reset boundaries overlap in retained history; this sample uses consecutive readings with one reset identity. Interleaved reset revisions split samples.")
	}
	if r.PollTiming {
		r.Notes = append(r.Notes, "Legacy quota polls retain receipt times, not call-start times; interval timing is approximate.")
	}
	r.Notes = append(r.Notes, "API-price equivalents measure recorded value per observed account quota point. External usage and provider reporting delays are not bounded by this range.")
	return r
}

func setNormalizedRates(r *ProfileNormalization) {
	if r.Delta <= 0 || r.Reference.InputPerMillion <= 0 {
		return
	}
	r.USDPerPercent = &ValueRange{float64(r.Contained.Low) / 1e9 / r.Delta, float64(r.Possible.High) / 1e9 / r.Delta}
	r.EquivalentPerPercent = &ValueRange{r.USDPerPercent.Low * 1e6 / r.Reference.InputPerMillion, r.USDPerPercent.High * 1e6 / r.Reference.InputPerMillion}
}

// Same provider/kind/pool only. Prefer the largest measured span when duplicate
// or revised windows overlap; each account/time interval acquires weight once.
func aggregateProfileRates(windows []QuotaUsageWindow, book ComparisonPriceBook) []ProfileRateGroup {
	groups := map[string][]QuotaUsageWindow{}
	for _, w := range windows {
		key := w.Provider + "|" + w.Kind + "|" + w.Scope
		groups[key] = append(groups[key], w)
	}
	out := []ProfileRateGroup{}
	for key, ws := range groups {
		first := ws[0]
		r := ProfileNormalization{RuleID: book.ID, Status: "unavailable", Reference: book.References[first.Provider], WindowIDs: []string{}, Notes: []string{"Historical rate = sum of matched API values / sum of measured quota points. Overlapping account intervals contribute once."}}
		sort.SliceStable(ws, func(i, j int) bool {
			a, b := ws[i].Normalization, ws[j].Normalization
			if a == nil {
				return false
			}
			if b == nil {
				return true
			}
			if a.Delta != b.Delta {
				return a.Delta > b.Delta
			}
			return ws[i].ID < ws[j].ID
		})
		used := map[string][]Binding{}
		for _, w := range ws {
			n := w.Normalization
			if book.Policy == profileValuePolicy && (w.Status == "superseded" || w.Valuation != nil && w.Valuation.Completion.Status == "uncertain") {
				r.Skipped++
				continue
			}
			if n == nil || n.Status != "available" {
				r.Skipped++
				continue
			}
			overlap := false
			for _, interval := range used[w.Account] {
				if n.From < interval.End && n.Through > interval.Start {
					overlap = true
					break
				}
			}
			if overlap {
				r.Skipped++
				continue
			}
			used[w.Account] = append(used[w.Account], Binding{Start: n.From, End: n.Through})
			r.Samples++
			r.Delta += n.Delta
			r.Contained.add(n.Contained)
			r.Possible.add(n.Possible)
			r.ContainedRequests += n.ContainedRequests
			r.BoundaryRequests += n.BoundaryRequests
			r.PollTiming = r.PollTiming || n.PollTiming
			if r.From == 0 || n.From < r.From {
				r.From = n.From
			}
			r.Through = max(r.Through, n.Through)
			r.WindowIDs = append(r.WindowIDs, w.ID)
		}
		if r.Samples > 0 {
			r.Status = "available"
			setNormalizedRates(&r)
		} else {
			r.Reason = "No comparable intervals in this pool and selection. Inspect a window for its coverage details."
		}
		out = append(out, ProfileRateGroup{key, first.Provider, first.Kind, first.Scope, r})
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}
